CREATE TABLE IF NOT EXISTS user_profiles (user_id TEXT PRIMARY KEY, selected_role TEXT NOT NULL DEFAULT 'victim' CHECK (selected_role IN ('victim','volunteer')), volunteer_status TEXT NOT NULL DEFAULT 'unverified' CHECK (volunteer_status IN ('unverified','pending_review','verified','rejected')), display_name TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());